#include <omp.h>
#include <vector>
#include <string>
#include <cstddef>
#include <algorithm>

struct Book {
    std::string title;
    int pages;
};

size_t findLastShortBook(std::vector<Book> const& books) {
    if (books.empty()) return static_cast<size_t>(-1);

    // Use a signed type for the reduction and loop index to avoid unsigned underflow.
    long long best = -1;

    #pragma omp parallel for reduction(max:best)
    for (long long i = 0; i < static_cast<long long>(books.size()); ++i) {
        if (books[static_cast<size_t>(i)].pages < 100) {
            best = std::max(best, i);
        }
    }

    return (best >= 0) ? static_cast<size_t>(best) : static_cast<size_t>(-1);
}
